import { useEffect, useState } from "react";
import Sidebar from "../components/Sidebar";
import {
  getTransactions,
  assessTransaction,
  transactionAction,
  getAuditLog,
} from "../services/api";
import "./HomeDashboard.css";

// ── Unified transaction ID formatter (mirrors backend fmt_txn_id) ─────────────
function fmtTxnId(id) {
  return `TXN-${String(id).padStart(8, "0")}`;
}

function RiskScoreGauge({ score }) {
  const color         = score >= 75 ? "#EF4444" : score >= 40 ? "#F59E0B" : "#10B981";
  const label         = score >= 75 ? "CRITICAL SEVERITY" : score >= 40 ? "MEDIUM SEVERITY" : "LOW RISK";
  const radius        = 54;
  const circumference = 2 * Math.PI * radius;
  const dashOffset    = circumference - (score / 100) * circumference;

  return (
    <div className="risk-gauge">
      <svg width="140" height="140" viewBox="0 0 140 140">
        <circle cx="70" cy="70" r={radius} fill="none" stroke="#E2E8F0" strokeWidth="10" />
        <circle
          cx="70" cy="70" r={radius}
          fill="none"
          stroke={color}
          strokeWidth="10"
          strokeDasharray={circumference}
          strokeDashoffset={dashOffset}
          strokeLinecap="round"
          transform="rotate(-90 70 70)"
          style={{ transition: "stroke-dashoffset 0.6s ease" }}
        />
        <text x="70" y="65" textAnchor="middle" fontSize="28" fontWeight="700" fill="#0F172A" fontFamily="DM Sans">
          {Math.round(score)}
        </text>
        <text x="70" y="82" textAnchor="middle" fontSize="11" fill="#94A3B8" fontFamily="DM Sans">
          / 100
        </text>
      </svg>
      <div className="risk-label" style={{ color }}>{label}</div>
    </div>
  );
}

function EngineBar({ value, max = 100 }) {
  const pct = Math.min((value / max) * 100, 100);
  return (
    <div className="engine-bar-track">
      <div className="engine-bar-fill" style={{ width: `${pct}%` }} />
    </div>
  );
}

function formatTime(timestamp) {
  if (!timestamp) return "";
  const date    = new Date(timestamp);
  const now     = new Date();
  const diffMin = Math.floor((now - date) / 60000);
  if (diffMin < 60) return `${diffMin}m ago`;
  return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function getRiskBadge(risk) {
  if (!risk) return null;
  if (risk === "HIGH")   return <span className="badge badge-danger">⚠ High Risk Flag</span>;
  if (risk === "MEDIUM") return <span className="badge badge-warning">⏳ Pending Review</span>;
  return <span className="badge badge-success">✓ Low Risk</span>;
}

// ── Filter Bar ────────────────────────────────────────────────────────────────
function FilterBar({ filters, onChange }) {
  return (
    <div className="filter-bar">
      <select
        className="filter-select"
        value={filters.status || "all"}
        onChange={(e) => onChange({ ...filters, status: e.target.value })}
      >
        <option value="all">All Statuses</option>
        <option value="pending">Pending</option>
        <option value="flag">Flagged</option>
        <option value="approve">Approved</option>
        <option value="review">In Review</option>
      </select>
      <select
        className="filter-select"
        value={filters.fraudClass ?? "all"}
        onChange={(e) =>
          onChange({
            ...filters,
            fraudClass: e.target.value === "all" ? null : Number(e.target.value),
          })
        }
      >
        <option value="all">All Classes</option>
        <option value={1}>Fraud (Class 1)</option>
        <option value={0}>Legit (Class 0)</option>
      </select>
    </div>
  );
}

// ── Audit Trail Modal ─────────────────────────────────────────────────────────
function AuditTrail({ txId, onClose }) {
  const [entries, setEntries] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getAuditLog(txId)
      .then((res) => {
        setEntries(res.data.audit_log || []);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [txId]);

  return (
    <div className="audit-overlay" onClick={onClose}>
      <div className="audit-modal" onClick={(e) => e.stopPropagation()}>
        <div className="audit-modal-header">
          <span>Audit Trail — {fmtTxnId(txId)}</span>
          <button className="audit-close" onClick={onClose}>✕</button>
        </div>
        {loading ? (
          <div className="audit-loading">Loading…</div>
        ) : entries.length === 0 ? (
          <div className="audit-empty">No audit entries yet.</div>
        ) : (
          <div className="audit-list">
            {entries.map((e) => (
              <div key={e.id} className="audit-row">
                <div className="audit-time">{new Date(e.created_at).toLocaleString()}</div>
                <div className="audit-scores">
                  ML: <strong>{e.ml_score?.toFixed(1)}</strong> ·
                  Anomaly: <strong>{e.anomaly_score?.toFixed(1)}</strong> ·
                  Rule: <strong>{e.rule_score?.toFixed(1)}</strong> →
                  Final: <strong style={{ color: e.risk_tier === "HIGH" ? "#EF4444" : e.risk_tier === "MEDIUM" ? "#F59E0B" : "#10B981" }}>
                    {e.final_score?.toFixed(1)} [{e.risk_tier}]
                  </strong>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ── Main Dashboard ────────────────────────────────────────────────────────────
function HomeDashboard() {
  const [transactions, setTransactions]   = useState([]);
  const [selectedTx, setSelectedTx]       = useState(null);
  const [risk, setRisk]                   = useState(null);
  const [loading, setLoading]             = useState(false);
  const [error, setError]                 = useState(null);
  const [riskCache, setRiskCache]         = useState({});
  const [search, setSearch]               = useState("");
  const [filters, setFilters]             = useState({ status: "all", fraudClass: null });
  const [limit, setLimit]                 = useState(20);
  const [loadingMore, setLoadingMore]     = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [actionMessage, setActionMessage] = useState(null);
  const [showAudit, setShowAudit]         = useState(false);

  // ── Load transactions (server-side filtering) ─────────────────────────────
  const loadTransactions = (lim = limit, searchVal = search, filtersVal = filters, append = false) => {
    return getTransactions(lim, { search: searchVal, ...filtersVal })
      .then((res) => {
        setTransactions(res.data.transactions || []);
        setError(null);
      })
      .catch(() => setError("Failed to load transactions"));
  };

  useEffect(() => {
    loadTransactions();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Re-fetch when filters change
  useEffect(() => {
    loadTransactions(limit, search, filters);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filters]);

  // Search with debounce
  useEffect(() => {
    const timer = setTimeout(() => loadTransactions(limit, search, filters), 350);
    return () => clearTimeout(timer);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [search]);

  const handleLoadMore = () => {
    const newLimit = limit + 20;
    setLimit(newLimit);
    setLoadingMore(true);
    loadTransactions(newLimit, search, filters)
      .finally(() => setLoadingMore(false));
  };

  // ── Risk assessment with caching ──────────────────────────────────────────
  useEffect(() => {
    if (!selectedTx) return;

    const txId = selectedTx.id;
    if (riskCache[txId]) {
      setRisk(riskCache[txId]);
      return;
    }

    setLoading(true);
    setRisk(null);

    const payload = {
      amount:         selectedTx.amount,
      transaction_id: txId,   // ← pass ID so audit log can reference it
      ...Object.fromEntries(
        Array.from({ length: 28 }, (_, i) => [
          `v${i + 1}`,
          selectedTx[`v${i + 1}`] ?? selectedTx[`V${i + 1}`] ?? 0,
        ])
      ),
    };

    assessTransaction(payload)
      .then((res) => {
        const result = {
          ...res.data.final_assessment,
          ml_score:      res.data.ml_details?.ml_score  ?? null,
          anomaly_score: res.data.anomaly_score          ?? null,
          rule_score:    res.data.rule_score             ?? null,
          weights_used:  res.data.weights_used           ?? null,
        };
        setRisk(result);
        setRiskCache((prev) => ({ ...prev, [txId]: result }));
      })
      .catch(() => setError("Risk assessment failed"))
      .finally(() => setLoading(false));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedTx]);

  // ── Transaction actions ───────────────────────────────────────────────────
  const handleAction = (action) => {
    if (!selectedTx) return;
    setActionLoading(true);
    setActionMessage(null);

    transactionAction({ transaction_id: selectedTx.id, action })
      .then(() => {
        const label =
          action === "flag"    ? "🚩 Flagged as Fraud — decision recorded"    :
          action === "approve" ? "✓ Transaction Approved — decision recorded" :
                                 "👁 Sent to Review — decision recorded";
        setActionMessage({ text: label, type: action });
        setTransactions((prev) =>
          prev.map((tx) => tx.id === selectedTx.id ? { ...tx, status: action } : tx)
        );
        setSelectedTx((prev) => ({ ...prev, status: action }));
        // Invalidate cache so a re-select re-fetches fresh
        setRiskCache((prev) => {
          const updated = { ...prev };
          delete updated[selectedTx.id];
          return updated;
        });
      })
      .catch(() => setActionMessage({ text: "Action failed", type: "error" }))
      .finally(() => setActionLoading(false));
  };

  return (
    <div className="layout">
      <Sidebar />
      <div className="main-content">
        {/* Header */}
        <div className="page-header">
          <h1 className="header-title">Fraud Monitoring Console</h1>
          <div className="header-search">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#94A3B8" strokeWidth="2">
              <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>
            </svg>
            <input
              placeholder="Search by transaction ID or amount…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
            />
          </div>
          <div className="header-actions">
            <button className="icon-btn">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/>
              </svg>
            </button>
          </div>
        </div>

        {/* Body */}
        <div className="home-body">
          {/* Left: Transaction List */}
          <div className="txn-panel">
            <div className="txn-panel-header">
              <span className="txn-panel-title">ACTIVE ALERTS</span>
              <span className="new-badge">{transactions.length}</span>
            </div>

            {/* Filter bar */}
            <FilterBar filters={filters} onChange={setFilters} />

            {error && <div className="error-msg">{error}</div>}

            <div className="txn-list">
              {transactions.length === 0 && !error && (
                <div className="empty-state">No transactions found</div>
              )}
              {transactions.map((tx) => {
                const cached     = riskCache[tx.id];
                const isSelected = selectedTx?.id === tx.id;
                return (
                  <div
                    key={tx.id}
                    className={`txn-item ${isSelected ? "txn-item--selected" : ""}`}
                    onClick={() => {
                      setSelectedTx(tx);
                      setActionMessage(null);
                    }}
                  >
                    <div className="txn-item-top">
                      {/* Unified ID format */}
                      <span className="txn-id">{tx.txn_ref || fmtTxnId(tx.id)}</span>
                      <span className="txn-time">{formatTime(tx.time_stamp)}</span>
                    </div>
                    <div className="txn-amount">${Number(tx.amount).toFixed(2)}</div>
                    <div>
                      {tx.status && tx.status !== "pending"
                        ? (() => {
                            if (tx.status === "flag")    return <span className="badge badge-danger">🚩 Flagged</span>;
                            if (tx.status === "approve") return <span className="badge badge-success">✓ Approved</span>;
                            if (tx.status === "review")  return <span className="badge badge-warning">👁 In Review</span>;
                            return null;
                          })()
                        : getRiskBadge(cached?.risk)}
                    </div>
                  </div>
                );
              })}

              <div className="load-more-wrap">
                <button className="load-more-btn" onClick={handleLoadMore} disabled={loadingMore}>
                  {loadingMore ? "Loading…" : "Load More"}
                </button>
              </div>
            </div>
          </div>

          {/* Right: Transaction Details */}
          <div className="details-panel">
            {!selectedTx ? (
              <div className="empty-details">
                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#CBD5E1" strokeWidth="1.5">
                  <rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20"/>
                </svg>
                <p>Select a transaction to view details</p>
              </div>
            ) : (
              <>
                <div className="card details-header-card">
                  <div>
                    <h2 className="details-title">Transaction Details</h2>
                    <p className="details-subtitle">
                      Reviewing transaction record for high-risk behaviour analysis
                    </p>
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", gap: 8, alignItems: "flex-end" }}>
                    {/* Unified ID — consistent everywhere */}
                    <span className="internal-id">
                      {selectedTx.txn_ref || fmtTxnId(selectedTx.id)}
                    </span>
                    <button
                      className="btn btn-outline"
                      style={{ fontSize: 12, padding: "4px 10px" }}
                      onClick={() => setShowAudit(true)}
                    >
                      📋 Audit Trail
                    </button>
                  </div>
                </div>

                <div className="details-grid">
                  <div className="card txn-info-card">
                    <div className="card-section-title">
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <circle cx="12" cy="12" r="10"/><path d="M12 8v4l3 3"/>
                      </svg>
                      TRANSACTION INFO
                    </div>
                    <div className="info-row">
                      <span className="info-label">Amount</span>
                      <span className="info-value amount-value">${Number(selectedTx.amount).toFixed(2)} USD</span>
                    </div>
                    <div className="info-row">
                      <span className="info-label">Transaction ID</span>
                      <span className="info-value mono">{selectedTx.txn_ref || fmtTxnId(selectedTx.id)}</span>
                    </div>
                    <div className="info-row">
                      <span className="info-label">Location</span>
                      <span className="info-value">{selectedTx.location || "Unknown"}</span>
                    </div>
                    <div className="info-row">
                      <span className="info-label">Date</span>
                      <span className="info-value">
                        {selectedTx.time_stamp
                          ? new Date(selectedTx.time_stamp).toLocaleString()
                          : "N/A"}
                      </span>
                    </div>
                    <div className="info-row">
                      <span className="info-label">Status</span>
                      <span className="info-value" style={{ textTransform: "capitalize" }}>
                        {selectedTx.status || "pending"}
                      </span>
                    </div>
                    {selectedTx.class !== undefined && selectedTx.class !== null && (
                      <div className="info-row">
                        <span className="info-label">Class</span>
                        <span className="info-value">
                          {selectedTx.class === 1
                            ? <span className="badge badge-danger">Fraud</span>
                            : <span className="badge badge-success">Legit</span>}
                        </span>
                      </div>
                    )}
                  </div>

                  <div className="card risk-card">
                    <div className="card-section-title">
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8M12 17v4"/>
                      </svg>
                      RISK CONFIDENCE SCORE
                    </div>
                    {loading ? (
                      <div className="loading-spinner">
                        <div className="spinner"/>
                        <p>Assessing…</p>
                      </div>
                    ) : risk ? (
                      <RiskScoreGauge score={risk.score} />
                    ) : (
                      <div className="no-risk">Fetching risk score…</div>
                    )}
                  </div>
                </div>

                {/* Engine Analysis */}
                {risk && (
                  <div className="card engine-card">
                    <div className="card-section-title">
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <circle cx="12" cy="12" r="3"/>
                        <path d="M12 2v2M12 20v2M2 12h2M20 12h2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"/>
                      </svg>
                      ENGINE ANALYSIS
                      {risk.weights_used && (
                        <span style={{ marginLeft: "auto", fontSize: 11, fontWeight: 400, color: "var(--text-muted)" }}>
                          Weights — Rule: {(risk.weights_used.rule * 100).toFixed(0)}% ·
                          ML: {(risk.weights_used.ml * 100).toFixed(0)}% ·
                          Anomaly: {(risk.weights_used.anomaly * 100).toFixed(0)}%
                        </span>
                      )}
                    </div>
                    <div className="engine-grid">
                      {/* Rule Engine */}
                      <div className="engine-col">
                        <div className="engine-label">RULE ENGINE</div>
                        <div className="engine-triggered">
                          <span className="trigger-dot" style={{
                            background: risk.rule_score > 0 ? "var(--danger)" : "var(--success)"
                          }}/>
                          {risk.rule_score > 0 ? "Triggered" : "Clear"}
                        </div>
                        <EngineBar value={risk.rule_score ?? 0} />
                        <div className="engine-detail">
                          Score: {risk.rule_score != null ? risk.rule_score.toFixed(1) : "—"}
                        </div>
                      </div>

                      {/* ML */}
                      <div className="engine-col">
                        <div className="engine-label">ML PROBABILITY</div>
                        <div className="engine-value">
                          {risk.ml_score != null
                            ? (risk.ml_score / 100).toFixed(3)
                            : (risk.score / 100).toFixed(3)}
                        </div>
                        <EngineBar value={risk.ml_score ?? risk.score} />
                        <div className="engine-detail">Model: XGBoost-Ensemble</div>
                      </div>

                      {/* Anomaly */}
                      <div className="engine-col">
                        <div className="engine-label">ANOMALY SCORE</div>
                        <div className="engine-value anomaly">
                          {risk.anomaly_score != null
                            ? (risk.anomaly_score / 100).toFixed(3)
                            : "—"}
                          <span className={`anomaly-tag ${
                            risk.risk === "HIGH"   ? "high" :
                            risk.risk === "MEDIUM" ? "med"  : "low"
                          }`}>
                            {risk.risk}
                          </span>
                        </div>
                        <EngineBar value={risk.anomaly_score ?? 0} />
                        <div className="engine-detail">Autoencoder reconstruction error</div>
                      </div>
                    </div>
                  </div>
                )}

                {/* Action Message */}
                {actionMessage && (
                  <div className={`action-message ${actionMessage.type}`}>
                    {actionMessage.text}
                  </div>
                )}

                {/* Action Buttons */}
                <div className="action-buttons">
                  <button className="btn btn-outline" onClick={() => handleAction("review")} disabled={actionLoading}>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8M12 17v4"/>
                    </svg>
                    Send to Review
                  </button>
                  <button className="btn btn-danger" onClick={() => handleAction("flag")} disabled={actionLoading}>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/>
                    </svg>
                    Flag as Fraud
                  </button>
                  <button className="btn btn-primary" onClick={() => handleAction("approve")} disabled={actionLoading}>
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <polyline points="20 6 9 17 4 12"/>
                    </svg>
                    Approve Transaction
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      </div>

      {/* Audit Trail Modal */}
      {showAudit && selectedTx && (
        <AuditTrail txId={selectedTx.id} onClose={() => setShowAudit(false)} />
      )}
    </div>
  );
}

export default HomeDashboard;
